class Solution {
public:
    int validSubarrays(vector<int>& nums) {
        stack<int> st;
        int answer = 0;
        for (int x : nums) {
            while (!st.empty() && st.top() > x) {
                st.pop();
            }
            st.push(x);
            answer += st.size();
        }
        return answer;
    }
};
